  function domainToAscii(domain) {
    // En ASCII, seuls les lettres, chiffres, tirets et points sont admis ;
    // les caractères non ASCII sont laissés à l'appréciation de la conversion IDNA.
    if (/[^A-Za-z0-9.\-\u0080-\u{10FFFF}]/u.test(domain)) return null;
    try {
