  // Aucune liste d'extensions ni longueur maximale d'extension autre que celle d'un label (63).
  function hostError(asciiHost) {
    if (asciiHost.length > 253) {
      return 'Le nom de domaine est trop long (253 caractères au maximum).';
    }
    var labels = asciiHost.split('.');
    if (labels.length < 2) {
