    var local = parts[0];
    var domain = parts[1];
    if (!local) return { error: 'Il manque la partie située avant le « @ ».' };
    if (!domain) return { error: 'Il manque le nom de domaine après le « @ ».' };

    var asciiDomain = domainToAscii(domain);
    if (asciiDomain === null) {
      return { error: 'Le nom de domaine « ' + domain + ' » n\'est pas valide.' };
    }
    var problem = hostError(asciiDomain);
    if (problem) return { error: problem };

    // La partie locale est conservée telle quelle (Unicode autorisé, RFC 6531).
    return { error: null, normalized: local + '@' + asciiDomain };
  }

  function validateWebsite(raw) {
    var value = raw.trim();
    if (!value) return { error: null, normalized: '' }; // champ facultatif
    if (/[\s\u0000-\u001F\u007F]/.test(value)) {
      return { error: 'L\'adresse du site ne doit pas contenir d\'espace.' };
    }
    var hasScheme = /^[a-z][a-z0-9+.\-]*:\/\//i.test(value);
    var url;
    try {
