    } catch (e) {
      return { error: 'Cette adresse de site n\'est pas valide. Exemple : https://société.fr' };
    }
    if (url.protocol !== 'http:' && url.protocol !== 'https:') {
      return { error: 'L\'adresse du site doit commencer par « http:// » ou « https:// ».' };
    }
    if (url.username || url.password) {
      return { error: 'L\'adresse du site ne doit pas contenir d\'identifiant ni de mot de passe.' };
    }
    var problem = hostError(url.hostname.replace(/\.$/, ''));
    if (problem) return { error: problem };
    return { error: null, normalized: url.href };
